interceptor-request.handler.py:
"""Gateway REQUEST interceptor.

The AgentCore Gateway calls this before every MCP request reaches a tool: initialize,
tools/list and tools/call. It hands back the request to send on, possibly changed, or
an answer of its own, which refuses the call. The Gateway may retry a call, so this
keeps no state and is safe to run twice.

Generated by AgentExpress from the templates checked on the Interceptors tab. Edit it
freely; generating it again from the tab replaces this file.

`event["mcp"]["gatewayRequest"]["headers"]` is there only with passRequestHeaders on.
The runtime then sends x-ax-session, x-ax-agent and x-ax-user with every call; the
Authorization header is the agent's own token, so never log the headers.
"""

import json
import logging

import re


logger = logging.getLogger()
logger.setLevel(logging.INFO)

VERSION = "1.0"

# What each checked template does, from the Interceptors tab.
SETTINGS = json.loads(r"""
{
    "audit": {},
    "argumentGuard": {
        "denyPatterns": [
            "(?i)drop\\s+table",
            "(?i)rm\\s+-rf"
        ],
        "maxArgumentChars": 20000
    }
}
""")


def _run(event: dict) -> dict:
    """The run this call belongs to, from the x-ax-* headers ("" when not passed)."""
    headers = {str(k).lower(): v for k, v in
               (((event.get("mcp") or {}).get("gatewayRequest") or {}).get("headers") or {}).items()}
    return {"session": str(headers.get("x-ax-session") or ""), "agent": str(headers.get("x-ax-agent") or ""),
            "user": str(headers.get("x-ax-user") or "")}


def _tool_of(body: dict) -> str:
    """The tool a tools/call names ("<toolKey>___<toolName>"), else ""."""
    return str((body.get("params") or {}).get("name") or "") if body.get("method") == "tools/call" else ""


def _refuse(body: dict, reason: str) -> dict:
    """Answer the call here instead of the tool: the agent sees this error."""
    return {"interceptorOutputVersion": VERSION, "mcp": {"transformedGatewayResponse": {
        "statusCode": 200,
        "body": {"jsonrpc": "2.0", "id": body.get("id"),
                 "error": {"code": -32001, "message": f"Refused by interceptor: {reason}"}}}}}


def audit(body: dict, run: dict, decision: str, reason: str = "") -> None:
    """One JSON line per request in CloudWatch Logs: what was called, by whom, and the
    decision. Argument NAMES only, never their values."""
    args = (body.get("params") or {}).get("arguments") if body.get("method") == "tools/call" else None
    logger.info(json.dumps({
        "interceptor": "request", "method": body.get("method"), "tool": _tool_of(body),
        "session": run["session"], "agent": run["agent"], "user": run["user"], "decision": decision,
        **({"reason": reason} if reason else {}),
        **({"arguments": sorted(args)} if isinstance(args, dict) else {}),
    }))


_DENIED = [re.compile(p) for p in (SETTINGS.get("argumentGuard") or {}).get("denyPatterns") or []]


def argument_guard(body: dict, run: dict) -> str | None:
    """Refuse a tool call whose arguments are too long or match a denied pattern."""
    if body.get("method") != "tools/call":
        return None
    text = json.dumps((body.get("params") or {}).get("arguments") or {}, ensure_ascii=False, default=str)
    limit = int((SETTINGS.get("argumentGuard") or {}).get("maxArgumentChars") or 20000)
    if len(text) > limit:
        return f"its arguments are {len(text)} characters, over the limit of {limit}"
    for rx in _DENIED:
        if rx.search(text):
            return f"its arguments match a denied pattern ({rx.pattern})"
    return None


# The checks, in order: the first that gives a reason refuses the call.
CHECKS = [
    argument_guard,
]


def lambda_handler(event, context):
    body = ((event.get("mcp") or {}).get("gatewayRequest") or {}).get("body") or {}
    run = _run(event)
    for check in CHECKS:
        reason = check(body, run)
        if reason:
            audit(body, run, "refused", reason)
            return _refuse(body, reason)
    audit(body, run, "allowed")
    return {"interceptorOutputVersion": VERSION, "mcp": {"transformedGatewayRequest": {"body": body}}}

interceptor-response.handler.py:
"""Gateway RESPONSE interceptor.

The AgentCore Gateway calls this after a tool answers and before the agent sees the
answer, for every MCP request: initialize, tools/list and tools/call. It hands back
the answer to deliver, possibly changed. The Gateway may retry a call, so this keeps
no state and is safe to run twice.

Generated by AgentExpress from the templates checked on the Interceptors tab. Edit it
freely; generating it again from the tab replaces this file.
"""

import copy

import json
import logging

import re


logger = logging.getLogger()
logger.setLevel(logging.INFO)

VERSION = "1.0"

# What each checked template does, from the Interceptors tab.
SETTINGS = json.loads(r"""
{
    "audit": {},
    "redactPii": {
        "mask": "[EMAIL REDACTED]",
        "types": [
            "email"
        ]
    }
}
""")


def _strings(value, fn):
    """`value` with fn applied to every string in it, however deeply nested."""
    if isinstance(value, str):
        return fn(value)
    if isinstance(value, list):
        return [_strings(v, fn) for v in value]
    if isinstance(value, dict):
        return {k: _strings(v, fn) for k, v in value.items()}
    return value


def _tool_of(request: dict) -> str:
    return str((request.get("params") or {}).get("name") or "") if request.get("method") == "tools/call" else ""


def _keep_protocol(sent: dict, changed, request: dict) -> dict:
    """The answer to deliver: what the steps changed in a TOOL'S RESULT, and every MCP
    protocol field exactly as the Gateway sent it.

    Only two things may change: a tools/call answer's `result` (or `error`), which is the
    tool's own output, and which tools a tools/list answer lists (an entry is dropped,
    never rewritten). Everything else, jsonrpc and id included, comes from `sent`, and any
    other method's answer (initialize: protocolVersion, capabilities, serverInfo; ping;
    notifications) is delivered untouched. A mask that matches a date or a version string
    then cannot break the MCP session, whatever the steps (custom included) do."""
    if not isinstance(changed, dict):
        return sent
    method = request.get("method")
    if method == "tools/call":
        out = {k: v for k, v in sent.items() if k not in ("result", "error")}
        out.update({k: changed[k] for k in ("result", "error") if k in changed})
        return out
    result = sent.get("result")
    if method == "tools/list" and isinstance(result, dict) and isinstance(result.get("tools"), list):
        listed = changed.get("result") if isinstance(changed.get("result"), dict) else {}
        names = {str(t.get("name")) for t in listed.get("tools") or [] if isinstance(t, dict)}
        return {**sent, "result": {**result, "tools": [
            t for t in result["tools"] if not isinstance(t, dict) or str(t.get("name")) in names]}}
    return sent


def audit(body: dict, request: dict) -> None:
    """One JSON line per answer in CloudWatch Logs: what was called, whether it failed,
    and how much came back. Never the content itself."""
    result = body.get("result")
    logger.info(json.dumps({
        "interceptor": "response", "method": request.get("method"), "tool": _tool_of(request),
        "error": bool(body.get("error")) or bool(isinstance(result, dict) and result.get("isError")),
        "resultChars": len(json.dumps(result, default=str)) if result is not None else 0,
    }))


_PII = {
    "card": re.compile(r"(?<!\d)\d(?:[ -]?\d){12,18}(?!\d)"),
    "ssn": re.compile(r"(?<!\d)\d{3}-\d{2}-\d{4}(?!\d)"),
    "phone": re.compile(r"(?<![\w+])(?:\+?\d{1,3}[ .-]?)?(?:\(\d{3}\)|\d{3})[ .-]?\d{3}[ .-]?\d{4}(?!\d)"),
    "email": re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}"),
}


def _luhn(text: str) -> bool:
    """A card number passes the Luhn check; most other long numbers do not."""
    digits = [int(c) for c in text if c.isdigit()][::-1]
    return sum(d if i % 2 == 0 else (d * 2 - 9 if d > 4 else d * 2) for i, d in enumerate(digits)) % 10 == 0


def redact_pii(body: dict, request: dict) -> dict:
    """Mask personal data in a tool's result. Patterns, so a backstop: a Bedrock
    guardrail is the managed check.

    Not a compliance control. Regex redaction does not meet PCI DSS, GDPR, HIPAA or
    similar obligations on its own; if real card numbers or personal data reach this
    tool, you are responsible for those controls under the AWS shared responsibility
    model. Use a Bedrock Guardrail sensitive-information filter as the managed control."""
    if request.get("method") != "tools/call" or "result" not in body:
        return body
    s = SETTINGS.get("redactPii") or {}
    kinds = [k for k in _PII if k in (s.get("types") or list(_PII))]
    mask = str(s.get("mask") or "[REDACTED]")

    def scrub(text: str) -> str:
        for kind in kinds:
            if kind == "card":
                text = _PII[kind].sub(lambda m: mask if _luhn(m.group(0)) else m.group(0), text)
            else:
                text = _PII[kind].sub(mask, text)
        return text

    body["result"] = _strings(body["result"], scrub)
    return body


# The changes, in order, each given the previous one's body.
STEPS = [
    redact_pii,
]


def lambda_handler(event, context):
    mcp = event.get("mcp") or {}
    request = (mcp.get("gatewayRequest") or {}).get("body") or {}
    response = mcp.get("gatewayResponse") or {}
    body = response.get("body")
    if isinstance(body, dict):
        # Copies taken before any step runs, so a step that changes the answer or the
        # request (its method included) cannot change what the guard below keeps.
        sent, asked = copy.deepcopy(body), copy.deepcopy(request)
        for step in STEPS:
            body = step(body, request)
        # Only a tool's result may change; every protocol field stays as sent.
        body = _keep_protocol(sent, body, asked)
        audit(body, request)
    out = {"body": body}
    # A streamed answer's later events carry no status: only the first one may set it.
    if "statusCode" in response:
        out["statusCode"] = response["statusCode"]
    return {"interceptorOutputVersion": VERSION, "mcp": {"transformedGatewayResponse": out}}

